/**
 * Specifies the position of the Tooltip or Popover relative to the anchor element.
 *
 * The available options are:
 * - `top` (default)&mdash;Aligns the tooltip above the anchor element.
 * - `bottom`&mdash;Aligns the tooltip below the anchor element.
 * - `right`&mdash;Aligns the tooltip with the rightmost point of the anchor element.
 * - `left`&mdash;Aligns the tooltip with the leftmost point of the anchor element.
 */
export type Position = 'top' | 'bottom' | 'right' | 'left';
